interface.definition:
a!localVariables(
  /*local!flagSubsecuente: if(*/
    /*a!isNotNullOrEmpty(ri!flagSubsecuente),*/
    /*null,*/
    /*null*/
  /*),*/
  local!flag1: if(
    and(
      a!isNotNullOrEmpty(ri!archivo.subproceso),
      ri!archivo.subproceso.identificador <> 101,
      ri!archivo.subproceso.identificador <> 121,
      ri!archivo.subproceso.identificador <> 105,
      ri!archivo.subproceso.identificador <> 9

    ),
    true,
    false

  ),
  local!flag2: if(
    and(
      a!isNotNullOrEmpty(ri!archivo.subproceso),
      or(
        ri!archivo.subproceso.identificador = 105,
        ri!archivo.subproceso.identificador = 9
      )
    ),
    true,
    false
  ),
  local!flag3: if(
    and(
      a!isNotNullOrEmpty(ri!archivo.subproceso),
      ri!archivo.subproceso.identificador = 121
    ),
    true,
    false
  ),
  local!showPopWarning: false,
  local!registersPerPage: 10,
  local!paginChoices: { 10, 20, 100 },
